<script setup>
import { watch, ref, onMounted } from 'vue';
import { storeToRefs } from "pinia";
import { getStatusFilter } from './utils';
import { useFVStore } from '../../../../stores/formvibes';

const store = useFVStore();
const i18n = window.fvGlobalVar?.i18n;
const {exportProfileData} = storeToRefs(store);

const data = exportProfileData.value;

const status = ref(getStatusFilter());
const title = ref(i18n?.select_status);

const statusSelected = ref(data.fv_status || []);

watch([statusSelected],() => {
    const data = statusSelected.value.map((stat) => (
        {
            key : stat,
            value: status.value.filter((sta) => sta.key === stat)[0].value,
        }
    ))
    exportProfileData.value.fv_status = data;
})
onMounted(() => {
    const savedStatus = exportProfileData.value.fv_status || [];
    const data = savedStatus.map((stat) => (
        stat.value
    ));
    statusSelected.value = data;
    
});
</script>
<template>
    <span className="fv-form-row-label fv-font-medium">
        {{ title }}
    </span>
    <div className="fv-form-row-value">
        <el-select v-model="statusSelected" placeholder="Select Status" multiple>
            <el-option
                v-for="item in status"
                :key="item.key"
                :label="item.value"
                :value="item.key"
            />
        </el-select>
    </div>
   
    
</template>