<script setup>
import { watch } from 'vue';
import { storeToRefs } from "pinia";
import Conditions from './conditions.vue';
import status from './status.vue';
import { Plus, CloseBold, RefreshRight } from "@element-plus/icons-vue"
import { useFVStore } from '../../../../stores/formvibes';
import { useFilterConditions, filterRelationOptions } from '../../../../stores/useFilterConditions';

const store = useFVStore();
const props = defineProps(['selectedForm', 'exportProfile']);
const i18n = window.fvGlobalVar?.i18n;
const { exportProfileData } = storeToRefs(store);

const { filters, addFilter, removeFilter, resetFilters } = useFilterConditions(exportProfileData.value.fv_filters || null);

watch([filters], () => {
    exportProfileData.value.fv_filters = filters.value;
});

watch([() => exportProfileData.value.fv_filters], () => {
    filters.value = exportProfileData.value.fv_filters;
});

const resetFilter = () => {
    resetFilters();
};
</script>

<template>
    <div class="fv-filter-wrapper fv-export-filter-wrapper">
        <div>
            <div class="fv-form-row" v-if="exportProfile != 'google-sheet'">
                <status />
            </div>
            <div class="fv-export-conditions">
                <div class="fv-form-row">
                    <span class="fv-form-row-label fv-font-medium">
                        {{
                            exportProfileData.fv_filter_relation === 'or' || exportProfileData.fv_filter_relation == '' ?
                            i18n?.or_condition_met_msg : i18n?.and_condition_met_msg
                        }}
                    </span>
                    <div class="fv-form-row-value">
                        <el-select v-model="exportProfileData.fv_filter_relation" placeholder="OR">
                            <el-option
                                v-for="item in filterRelationOptions"
                                :key="item.value"
                                :label="item.label"
                                :value="item.value"
                            />
                        </el-select>
                    </div>
                </div>
                <Conditions v-for="(filter,index) in filters" v-model:filterData="filters[index]" :key="index" :removeFilter="removeFilter" :id="index" :columns="exportProfileData?.fv_fields?.cols" />
                <div @click="addFilter" class="fv-export-add-condition">
                    <el-icon><Plus /></el-icon>
                    <span>{{i18n?.add_new_condition}}</span>
                </div>
                <div class="fv-filter-action">
                    <el-button type="danger" @click="resetFilter" :icon="RefreshRight" plain class="fv-filter-reset">{{i18n?.reset}}</el-button>
                </div>
            </div>
        </div>
    </div>
</template>
