<script setup>
import { watch, ref, onMounted } from 'vue';
import { storeToRefs } from "pinia";
import { useFVStore } from '../../../stores/formvibes';

const i18n = window.fvGlobalVar?.i18n;

const store = useFVStore();
const { exportProfileData } = storeToRefs(store);
const mappedColumns = ref(exportProfileData.value?.fv_mapped_columns || []);
const sheet_headers = ref(exportProfileData.value.sheet_headers);
const excluded_columns = ref(exportProfileData.value?.excluded_columns || []);
const defaultChecked = ref([]);

onMounted(() => {
    sheet_headers.value = exportProfileData.value.sheet_headers || mappedColumns.value;
})

watch([() => exportProfileData.value.sheet_headers], () => {
    const mapCols = exportProfileData.value?.fv_mapped_columns || [];

    let sheetCols = [];

    Object.keys(exportProfileData.value.sheet_headers).forEach((col) => {
        sheetCols ={
            ...sheetCols,
            [col] : mapCols[col] || '',
        }
    })
    mappedColumns.value = sheetCols;
})

watch([mappedColumns], () =>{
    exportProfileData.value.fv_mapped_columns = mappedColumns.value;
})

const checkChange = (event,index) => {
    const mapColValue = mappedColumns.value[index];

    if(event){
        excluded_columns.value = excluded_columns.value.filter((col) => col !== mapColValue);
    }
    else{
        excluded_columns.value = [...excluded_columns.value, mappedColumns.value[index]];
    }

    exportProfileData.value = {
        ...exportProfileData.value,
        excluded_columns:  excluded_columns.value
    };
}
const getIsExcluded = (header) => {
    return !exportProfileData.value.excluded_columns.includes(header);
}
</script>
<template>
    <div>
        <div class="fv-col-header">
            <span class="fv-field-fname">{{i18n?.sheet_headers}}</span>
            <span class="fv-field-cname"> {{i18n?.form_fields}}</span>
        </div>
        <div>
            <div v-for="(header, index) in exportProfileData.fv_mapped_columns" :key="index" class="fv-sheet-col-item">
                <el-checkbox :checked="getIsExcluded(header)" @change="checkChange($event,index)"/>
                <div class="fv-settings-item" >
                    <span class="fv-field-col-header" :class="{ disabled : false == getIsExcluded(header) }"> {{ sheet_headers[index] }}</span>
                    <span>
                        <el-select v-model="mappedColumns[index]" placeholder="Select">
                            <el-option
                                v-for="item in exportProfileData.fv_fields.cols.filter((col) => col.colKey !== 'fv_status')"
                                :key="item.colKey"
                                :label="item.alias"
                                :value="item.colKey"
                            />
                        </el-select>
                    </span>
                </div>
            </div>
        </div>
    </div>
</template>