<script setup>
import { watch, ref, onMounted } from 'vue';
import { storeToRefs } from "pinia";
import { useFVStore } from '../../../stores/formvibes';
import ExportFilter from './filter/filter.vue';
import { View, Hide, Delete, Download, WarnTriangleFilled, CircleCloseFilled, CirclePlusFilled, Refresh } from '@element-plus/icons-vue';
import { axiosPost } from '../../../Axios/post';
import ColumnsMapping from './column-mapping.vue';
import { shortcuts } from '../../../stores/utils';


const i18n = window.fvGlobalVar?.i18n;
const client_id = window.fvGlobalVar?.client_id;
let keyMissing = false;
if(!client_id || !window.fvGlobalVar?.has_client_secret){
    keyMissing = true
}
const store = useFVStore();
const { formsSelector,defaultDates, exportProfileData, isLoading,notice } = storeToRefs(store); 
const tempColum = ref([]);
const fvData = exportProfileData.value;
const selectedExportProfile = ref(fvData?.fv_export_profile_type || 'local-download');
const mappedColumns = ref([]);
const preset = ref('Custom');
const selectedSpreadsheet = ref( exportProfileData.value.fv_spreadsheet_id || '');
const selectedWorksheet = ref( exportProfileData.value.fv_worksheet_id || '');
const isDeleteOpen = ref(false);
const currentPage = ref(1);
const perPage = ref(10);
const files = ref([]);
const excluded_columns = ref([]);
const filesCount = ref(exportProfileData.value.export_files ? exportProfileData.value.export_files.length : 0) ;
const deleteStates = ref({
    loading: false,
    error: false,
})
const spreadsheetsGoogle = exportProfileData.value?.spreadsheets?.data || [];
const spreadSheets = ref(spreadsheetsGoogle || [])
const spreadsheetsBackup = ref(spreadsheetsGoogle);
const filteredWorksheets = ref(exportProfileData.value?.worksheets?.data || []);
const worksheets = ref(exportProfileData.value?.worksheets?.data?.map((w) => {
                                    const { id, name } = w;
                                    return {
                                        value: id.toString(),
                                        label: name,
                                    };
                                }) || []);

const spreadsheetsIds = spreadSheets.value?.map((sheet) => sheet.id);
const spredsheetOptions =  spreadSheets.value.map((s) => {
												const { id, name } = s;
												return {
													value: id,
													label: name,
												};
											})
											.filter(
												({ key }, index) =>
													!spreadsheetsIds.includes(key, index + 1)
											)
// const filterRelation = ref(fvData?.fv_filter_relation || 'or');
const fileType = ref('csv');

const ajax_nonce = window.fvGlobalVar.ajax_nonce;
const forms = formsSelector.value;
const savedFormData = ref(exportProfileData.value?.fv_data_source?.split(':'));
const selectedForm = ref('');
const form = ref('');
const plugin = ref('');
const columns = ref(exportProfileData.value.fv_fields.cols);
const isSearchingWorksheet = ref(false);
const isSpreadsheetAdd = ref(false);
const isWorksheetAdd = ref(false);
const sheetName = ref('');
const worksheetName = ref('');
const askAddColumns = ref(false);
const askAddColumnsDialog = ref(false);
const defaultChecked = ref([]);

// add a watcher on selectedForm
watch([selectedForm], async () => {
   
})

watch([notice], () => {
    ElNotification({
        offset: 30,
        dangerouslyUseHTMLString: true,
        message: `<strong>${notice.value.message}</strong>`,
        type: notice.value.isError ? 'error' : 'success',
        class:'fv-items-center'
    })
})

onMounted(async () => {
    let dataSource = exportProfileData.value.fv_data_source?.split(':');
    if(!dataSource[0]){
        const firstForm = forms[0]['options'][0];
        dataSource[0] = firstForm.plugin;
        dataSource[1] = firstForm.value;
        selectedForm.value = firstForm.value;
        plugin.value = firstForm.plugin;
        form.value = firstForm.value;
    }
    plugin.value = dataSource[0];
    form.value = dataSource[1] ;
    selectedForm.value = dataSource[1];

    files.value = exportProfileData.value.export_files;
    const dates = exportProfileData.value.fv_date_range;
    let shortcut = '';
    if(selectedExportProfile.value == 'local-download'){
        let isOldColumns = false;
        if (
            savedFormData.value.length > 1 &&
            // eslint-disable-next-line eqeqeq
            plugin.value == savedFormData.value[0] &&
            // eslint-disable-next-line eqeqeq
            form.value == savedFormData.value[1]
        ) {
            isOldColumns = true;
        }else{
            isOldColumns = false;
        }
        if(isOldColumns){
            columns.value = exportProfileData.value.fv_fields.cols;
        }else{
            let columnsPrepared = await getColumns();
            columns.value = columnsPrepared;
        } 
    }
    
    if(selectedExportProfile.value == 'google-sheet'){
        let columnsPrepared = await getColumns();        
        columns.value = columnsPrepared;
        exportProfileData.value.fv_fields = {
            cols : columnsPrepared
        };
    }

    if(exportProfileData.value.fv_fields == undefined || exportProfileData.value.fv_fields.cols == undefined){
        exportProfileData.value.fv_fields = {
            cols : columns.value
        };
    }
    if(!dates){
        shortcut = shortcuts.filter((shortcut) => {
            return shortcut.text === 'This Year';
        })[0]
    }
    else{
        shortcut = shortcuts.filter((shortcut) => {
            return shortcut.text === dates.queryType.replaceAll('_', ' ');
        })[0];
    }
    
    if(shortcut && shortcut.text !== 'Custom') {
        preset.value = dates.queryType;
        defaultDates.value = [
            shortcut.value()[0].format('YYYY-MM-DD'),
            shortcut.value()[1].format('YYYY-MM-DD')
        ];
    }else{
        preset.value = 'Custom';
        defaultDates.value = [
            dates.fromDate,
            dates.toDate
        ];
    }
});


watch([defaultDates], async () => {
    const shortcut = shortcuts.filter((shortcut) => {
        const [start, end] = shortcut.value();

        return start.format('YYYY-MM-DD') === defaultDates.value[0] && end.format('YYYY-MM-DD') === defaultDates.value[1];
    })[0];
    
    if(!shortcut) {
      preset.value = 'Custom';
    }
    else{
      preset.value = shortcut.text.replaceAll(' ', '_');
    }
});

// watch([selectedForm], async () => {
//     console.log('trigger');
//     const columnsPrepared = await getColumns();
//     columns.value = columnsPrepared;
//     exportProfileData.value.fv_fields = {
//         cols : columnsPrepared
//     };
// })


const profileType = ref([
    {
		value: 'local-download',
		label: i18n?.local_download,
	},
	{
		value: 'google-sheet',
		label: i18n?.google_sheet,
	},
]);

const onChangeForm = async (id, e) => {
    const formSelected = forms.filter((form) => form.label === e.label)[0].options.filter((fm) => fm.value === id)[0];
    form.value = formSelected.value;
    plugin.value = formSelected.plugin;
    if(plugin.value == 'caldera' && selectedExportProfile.value == 'google-sheet'){
        notice.value = {
            ...notice.value,
            type: 'error',
            isError: true,
            message: 'Caldera forms can not be exported to Google Sheet',
        }
        return;
    }
    exportProfileData.value.fv_filters = [{
            filter: '',
            key: '',
            operator: 'LIKE',
            value: '',
    }];
    let columnsPrepared = await getColumns();
    columns.value = columnsPrepared;
    exportProfileData.value.fv_fields = {
        cols : columnsPrepared
    };

}

const getColumns = async () => {
    const { data } = await axiosPost({
        action: 'fv_get_columns',
        queryParams: {
            formId: form.value,
            plugin: plugin.value,
        },
    });
    
    let columns = [];
    if(selectedExportProfile.value == 'google-sheet'){
        columns = data.columns.filter((col) => col.colKey !== 'fv_status');
    }else{
        columns = data.columns;
    }
    const columnsPrepared = prepareColumns(columns);
    return columnsPrepared;
};


const prepareColumns = (columns) => {
    let isOldColumns = false;
    if (
        savedFormData.value.length > 1 &&
        // eslint-disable-next-line eqeqeq
        plugin.value == savedFormData.value[0] &&
        // eslint-disable-next-line eqeqeq
        form.value == savedFormData.value[1]
    ) {
        isOldColumns = true;
    }

    const savedCols = columns;
    if(savedCols){
         defaultChecked.value = savedCols.map((col) => col.colKey);
    }
    
    return columns;
    // When changing form it will added the field of other form in columns
    if (isOldColumns) {
        console.log('dfds');
        columns.forEach((col) => {
            if (!savedCols.find((sCol) => sCol.colKey === col.colKey)) {
                savedCols.push({
                    ...col,
                });
            }
        });
    }

    if (isOldColumns) return savedCols;
    return columns;
};

const changeVisible = (e) => {

    e.visible = !e.visible    
}

const onDeleteIcon = (row) => {
    isDeleteOpen.value = true;
    deleteStates.value = {
        fileName: row.file_name,
    }
}
const resetDeleteStates = () => {
    deleteStates.value = {
        loading:false,
        error:false,
    }
};

const onDelete = async () => {
    deleteStates.value = {
        ...deleteStates.value,
        loading:true,
    }
    isLoading.value = true;
    try {
        const { data } = await axiosPost({
            queryParams: {
                fileName: deleteStates.value.fileName,
                post_id: fvData.post_id,
            },
            action: 'fv_delete_export_file',
        });
        const resp = data;
        if (resp.is_error) {
            throw new Error(resp.message);
        }
        
        exportProfileData.value.export_files = exportProfileData.value.export_files.filter((f) => f.file_name !== deleteStates.value.fileName);
        files.value = exportProfileData.value.export_files;

        notice.value = {
            ...notice.value,
            type: 'success',
            message: resp.message,
        }

        if(files.value.length < 11 ){
            currentPage.value = 1;
            perPage.value = 10;
        }
        isDeleteOpen.value = false;
    } catch (error) {
        notice.value = {
            ...notice.value,
            type: 'error',
            isError : true,
            message: error.message,
        }
    } finally {
        isLoading.value = false;
    }
}

const handleSizeChange = (val) => {
    perPage.value = val;
}
const handleCurrentChange = (val) => {
    currentPage.value = val;
}

const getWorksheets = async () => {
    isSearchingWorksheet.value = true;
    try {
        const { data } = await axiosPost({
            queryParams: {
                spreadsheet_id: selectedSpreadsheet.value,
            },
            action: 'fv_get_worksheets',
        });
        if (data.success) {
            const sheets = [...data.data];
            worksheets.value = sheets.map((w) => {
                                    const { id, name } = w;
                                    return {
                                        value: id,
                                        label: name,
                                    };
                                });
        }
    } catch (error) {
        notice.value = {
            ...notice.value,
            type: 'error',
            isError: true,
            message: error.message,
        }
    } finally {
        isSearchingWorksheet.value = false;
    }
};

const getHeaders = async () => {
    if(selectedSpreadsheet?.value == '' || selectedWorksheet?.value?.toString() == ''){
        return;
    }
    isSearchingWorksheet.value = true;
    try {
			const { data } = await axiosPost({
				queryParams: {
					spreadsheet_id: selectedSpreadsheet.value,
					worksheet_name:
						worksheets.value.find(
							(s) => s.value.toString() === selectedWorksheet.value.toString()
						)?.label || '',
				},
				action: 'fv_get_headers',
			});

			if (data.success) {
				exportProfileData.value.sheet_headers = data.data;
			} else {
				const { status } = data.data;
				if (status === 'NO_HEADERS') {
                    exportProfileData.value.sheet_headers = {};
                    askAddColumns.value = true;
				}
			}
		} catch (error) {
            notice.value = {
                ...notice.value,
                type: 'error',
                isError: true,
                message: error.message,
            }
		} finally {
            isSearchingWorksheet.value = false
		}
}
watch([selectedSpreadsheet],() => {
    getWorksheets();
})

watch([selectedWorksheet],() => {
    getHeaders();
})

watch([perPage,currentPage],() => {
    const filesData = [...window.fv_export_profiles_data.export_files];
    const newData = filesData.slice((currentPage.value - 1) * perPage.value , ( currentPage.value * perPage.value));

    files.value= newData;
})

const addSpreadsheet = async () =>{
    isLoading.value = true;
    try {
        const { data } = await axiosPost({
            queryParams: {
                name: sheetName.value,
            },
            action: 'fv_create_spreadsheet',
        });
        const sheets = data.data;
        if (data.success) {

            // Update the spreadsheetsBackup with the new spreadsheet
            // spreadsheets.data.unshift(data.data);
            spreadSheets.value.unshift({
                value: data.data.id,
                label: data.data.name,
            });
            // Update the spreadsheetsBackup with the new spreadsheet  
            spreadsheetsBackup.value = {
                ...spreadsheetsBackup.value,
                sheets
            };
            selectedSpreadsheet.value = data.data.id;
            notice.value = {
                ...notice.value,
                type: 'success',
                message: 'Spreadsheet created successfully',
            }
            isSpreadsheetAdd.value = false;
            selectedWorksheet.value = '';
            mappedColumns.value = {};
            sheetName.value = '';
            exportProfileData.value.fv_spreadsheet_id = data.data.id;
        } else {
            notice.value = {
                ...notice.value,
                type: 'error',
                isError: true,
                message: 'spreadsheet could not be created',
            }
        }
    } catch (error) {
        notice.value = {
            ...notice.value,
            type: 'error',
            isError: true,
            message: error.message,
        }
    } finally {
        isLoading.value = false;
    }
}
const addWorksheet = async () => {
    isLoading.value = true;
    try {
        const { data } = await axiosPost({
            queryParams: {
                spreadsheet_id: selectedSpreadsheet.value,
                name: worksheetName.value,
            },
            action: 'fv_create_worksheet',
        });

        if (data.success) {
            const newWorksheets = worksheets.value.slice();
            newWorksheets.unshift({value: data.data.id, label:data.data.name});
            worksheets.value = newWorksheets;
            mappedColumns.value = {};
            notice.value = {
                ...notice.value,
                type: 'success',
                message: 'Worksheet created successfully',
            }
            isWorksheetAdd.value = false;
            selectedWorksheet.value = data.data.id;
        } else {
            notice.value = {
                ...notice.value,
                type: 'error',
                isError: true,
                message: 'Worksheet could not be created',
            }
        }
    } catch (error) {
        notice.value = {
                ...notice.value,
                type: 'error',
                isError: true,
                message: error.message,
            }
    } finally {
        isLoading.value = false;
    }
};
const allowDrop = (draggingNode, dropNode, type) => {
    if(type === 'inner'){
        return false;
    }
    return true
}

const onCheckChange = (data, checked, indeterminate) => {

    exportProfileData.value.fv_fields.cols.map((col) => {
        if(col.colKey === data.colKey){
            col.visible = checked;
            excluded_columns.value.push(col.colKey);
        }
    })
    exportProfileData.value = {
        ...exportProfileData.value,
        excluded_columns:  excluded_columns.value
    };
}

const setHeaders = async () => {
    isLoading.value = true;
    const worksheetHeaders = exportProfileData.value.fv_fields.cols
        .filter((column) => column.visible)
        .map((column) => column.colKey);
    try {
        const { data } = await axiosPost({
            queryParams: {
                spreadsheet_id: selectedSpreadsheet.value,
                worksheet_name:
                    worksheets.value.find(
                        (s) => s.value.toString() === selectedWorksheet.value.toString()
                    )?.label || '',
                headers: worksheetHeaders,
            },
            action: 'fv_add_headers',
        });
        if (data.success) {
            // add notification here
            notice.value = {
                ...notice.value,
                type: 'success',
                message: 'Headers added successfully',
            }
            const createdHeaders = {};
            askAddColumns.value = false;
            const alphabets = Array.from(Array(26))
                .map((e, i) => i + 65)
                .map((x) => String.fromCharCode(x));
            worksheetHeaders.forEach((header, index) => {
                createdHeaders[alphabets[index]] = worksheetHeaders[index];
            });
            
            exportProfileData.value.sheet_headers = createdHeaders;
            exportProfileData.value.fv_mapped_columns = createdHeaders;
            
            askAddColumnsDialog.value = false;
        } else {
            notice.value = {
                ...notice.value,
                type: 'error',
                isError: true,
                message: 'Headers could not be added',
            }
        }
    } catch (error) {
        notice.value = {
            ...notice.value,
            type: 'error',
            isError: true,
            message: error.message,
        }
    } finally {
        isLoading.value = false;
    }
};
</script>
<template>
    <el-config-provider>
        <!-- Add Delete Exported Entry Dialoge -->
        <el-dialog 
            v-model="isDeleteOpen" 
            :with-header="true"
            :show-close=true
            @close="closeDialog"
            align-center="true"
            class = "fv-export-delete-dialog"
            width="600px"
        >
            <template #header="{ close, titleId, titleClass }">
                <div class="fv-header-title">
                    <el-icon size="20">
                        <WarnTriangleFilled />
                    </el-icon>
                    <strong>{{i18n?.delete_entry}}</strong>
                </div>
            </template>
            <div v-if="!isLoading">Are you sure you want to delete?</div>
            <div v-else class="fv-export-delete-loading">
                <el-icon size="50" ><Refresh /></el-icon>
            </div>
            <template #footer="">
                <el-button @click="isDeleteOpen = false">Cancel</el-button>
                <el-button type="danger" @click="onDelete">Delete</el-button>
            </template>
        </el-dialog>

        <!-- Add Spreadsheet Dialoge -->
        <el-dialog 
        v-model="isSpreadsheetAdd" 
        :with-header="true"
        :show-close="true"
        @close="closeDialog"
        width="35%"
        align-center="true"
        class="fv-export-add-spreadsheet-dialog"
        >
            <template #header>
                <div class="fv-header-title">
                    <el-icon size="20">
                        <WarnTriangleFilled />
                    </el-icon>
                    <strong>Add Spreadsheet</strong>
                </div>
            </template>
            <div>
                <el-input v-model="sheetName" placeholder="Enter Spreadsheet Name"/>
            </div>
            <template #footer>
                <el-button @click="isSpreadsheetAdd = false">Cancel</el-button>
                <el-button type="primary" @click="addSpreadsheet">Add</el-button>
            </template>
        </el-dialog>
        <!-- Add WorkSheet Dialog -->
        <el-dialog 
        v-model="isWorksheetAdd" 
        :with-header="true"
        :show-close="true"
        @close="closeDialog"
        width="35%"
        class="fv-export-add-worksheet-dialog"
        align-center="true"
        >
            <template #header="{ close, titleId, titleClass }">
                <div class="fv-header-title">
                    <el-icon size="20">
                        <WarnTriangleFilled />
                    </el-icon>
                    <strong>Add Worksheet</strong>
                </div>            
            </template>
            <div>
                <el-input v-model="worksheetName" placeholder = "Add Worksheet Name"/>
            </div>

            <template #footer="">
                <el-button @click="isWorksheetAdd = false">Cancel</el-button>
                <el-button type="primary" @click="addWorksheet">Add</el-button>
            </template>
        </el-dialog>

        <!-- Add Columns Dialog after google sheet added-->
        <el-dialog 
        v-model="askAddColumnsDialog" 
        :with-header="true"
        :show-close="true"
        @close="closeDialog"
        width="560px"
        class="fv-export-add-columns-dialog"
        >   
            <template #header>
                <div class="fv-header-title">
                    <el-icon size="20">
                        <WarnTriangleFilled />
                    </el-icon>
                    <strong>Add Columns</strong>
                </div>
            </template>
            <div>
                
                <div class="fv-col-header">
                    <span class="fv-field-fname">Field Name</span>
                    <span class="fv-field-cname">Column Name</span>
                </div>
                <el-tree
                    :allow-drop="allowDrop"
                    allow-drag="true"
                    draggable
                    default-expand-all
                    node-key="colKey"
                    :data="exportProfileData.fv_fields.hasOwnProperty('cols') ? exportProfileData.fv_fields.cols : columns"
                    show-checkbox
                    @check-change="onCheckChange"
                    :default-checked-keys="defaultChecked"
                >
                    <template  #default="{ node, data }">
                        <div class="fv-settings-item">
                            <span class="fv-field-col-header">{{ data.colKey }}</span>
                            <el-input v-model="data.colKey" placeholder="Please input" />
                        </div>
                    </template>
                </el-tree>
            </div>

            <template #footer="">
                <el-button @click="askAddColumnsDialog = false">Cancel</el-button>
                <el-button type="primary" @click="setHeaders">Add</el-button>
            </template>
        </el-dialog>
        <div class="fv-export-profile-wrapper">
            <div class="">
                <input name="fv_mapped_columns" :value="`${JSON.stringify(exportProfileData?.fv_mapped_columns)}`" type="hidden" />
                <input name="fv_sheet_columns" :value="`${JSON.stringify(exportProfileData?.sheet_headers)}`" type="hidden" />
                <input name="excluded_columns" :value="`${JSON.stringify(exportProfileData?.excluded_columns)}`" type="hidden" />
                <input name="fv_spreadsheet_id" :value="selectedSpreadsheet" type="hidden" />
				<input name="fv_worksheet_id" :value="selectedWorksheet" type="hidden" />
                <input name="fv_ep_download_file_type" :value="fileType" type="hidden" />
                <input name="fv_export_profile_type" :value="selectedExportProfile" type="hidden" />
                <input name="fv_data_source" :value="`${plugin}:${form}`" type="hidden" />
                <input type="hidden" :value="`${ajax_nonce}`" name="ajaxNonce" />
                <input type="hidden" name="fv_date_range[queryType]" :value="preset" />
                <input type="hidden" name="fv_date_range[fromDate]" :value="defaultDates[0]" />
                <input type="hidden" name="fv_date_range[toDate]" :value="defaultDates[1]" />
                <input name="fv_fields" :value="`${JSON.stringify(columns)}`" type="hidden" />
				<input name="fv_show_on_expand" value="false" type="hidden" />
                <input name="fv_filters" :value="`${JSON.stringify(exportProfileData.fv_filters)}`" type="hidden" />
                <input name="fv_filter_relation" :value="exportProfileData.fv_filter_relation" type="hidden" />
                <input
					name="fv_status"
					:value="`${JSON.stringify(
						Object.values(exportProfileData.fv_status).map(
							({ value, key }) => ({
								label: value,
								value: key,
							})
						)
					)}`"
					type="hidden"
				/>
            </div>
            <div class="fv-export-header" style="display:flex; align-items: center; gap: 20px;">

                <span >Profile Type</span>
                <el-select v-model="selectedExportProfile" placeholder="Select">
                    <el-option
                        v-for="item in profileType"
                        :key="item.value"
                        :label="item.label"
                        :value="item.value"
                    />
                </el-select>
            </div>
            
            <div class="fv-export-content" style="position: relative;">
                <div v-if="selectedExportProfile == 'google-sheet' && keyMissing" class="fv-gs-notice">
                    <el-button
                        type="primary"
                        tag="a"
                        href="admin.php?page=fv-db-settings#gsheet"
                        target="_blank"
                    >
                    Add Authentication
                    </el-button>
                </div>
                <el-tabs tab-position="left" type="border-card">
                    <el-tab-pane label="Data Source" class="fv-settings-export-ds">
                        <div class="fv-form-row">
                            <span>Form</span>
                            <el-select v-model="selectedForm" placeholder="Select">
                                <el-option-group
                                    v-for="group in forms"
                                    :key="group.label"
                                    :label="group.label"
                                    >
                                    <el-option
                                        v-for="item in group.options"
                                        :key="item.value"
                                        :label="item.label"
                                        :value="item.value.toString()"
                                        @click="(e) => onChangeForm(item.value,group)"
                                    />
                                </el-option-group>
                            </el-select>
                        </div>
                        <div class="fv-form-row" v-if="selectedExportProfile === 'google-sheet'">
                            <span>Spreadsheets</span>
                            <el-select v-model="selectedSpreadsheet" placeholder="Select">
                                <el-option
                                    v-for="item in spredsheetOptions"
                                    :key="item.value"
                                    :label="item.label"
                                    :value="item.value"
                                />
                            </el-select>
                            <el-icon @click="isSpreadsheetAdd = true"><CirclePlusFilled /></el-icon>
                        </div>
                        <div class="fv-form-row" v-if="selectedExportProfile === 'google-sheet'">
                            <span>Worksheet</span>
                                <el-select
                                    v-model="selectedWorksheet"
                                    filterable
                                    remote
                                    reserve-keyword
                                    placeholder="Please enter a keyword"
                                    class="fv-export-ws-select"
                                >
                                    <el-option v-for="item in worksheets"
                                        :key="item.value"
                                        :label="item.label"
                                        :value="item.value"
                                    />
                                </el-select>
                                <el-icon @click="isWorksheetAdd = true"><CirclePlusFilled /></el-icon>
                        </div>
                        <div v-if="askAddColumns && !isSearchingWorksheet" class="fv-export-column-notice">
                            We did not find the columns in the spreadsheet. Add them
								manually or <el-link @click="askAddColumnsDialog = true" class="fv-header-link">Click Here</el-link>
                                to add them
                        </div>
                        <div v-if="selectedExportProfile != 'google-sheet'" class="fv-form-row">
                            <span>Date Range</span>
                            <el-date-picker
                                v-model="defaultDates"
                                type="daterange"
                                unlink-panels
                                range-separator="To"
                                start-placeholder="Start Date"
                                end-placeholder="End date"
                                popper-class="wml-date-picker-popup"
                                size="default"
                                :shortcuts="shortcuts"
                                value-format="YYYY-MM-DD"
                                format="DD/MM/YYYY"
                                :clearable="false"
                            />
                        </div>
                        <div class="fv-export-filter-section">
                            <span class="fv-export-filter-heading">Data Filter</span>
                            <ExportFilter :selectedForm="selectedForm" :exportProfile = "selectedExportProfile"/>
                        </div>
                    </el-tab-pane>
                    <el-tab-pane label="Fields" v-if="selectedExportProfile != 'google-sheet'">
                        <div class="fv-export-setting-col-header">
                            <span class="fv-setting-label">
                                {{i18n?.field_name}}
                            </span>
                            <span>
                                {{i18n?.column_label}}
                            </span>
                            <span>
                                {{i18n?.column_visibility}}
                            </span>
                        </div>
                        <el-tree
                                :allow-drop="allowDrop"
                                allow-drag="true"
                                draggable
                                default-expand-all
                                node-key="ids"
                                :data="columns"
                            >
                                
                                <template #default="{ node, data }">
                                    <div class="fv-settings-item">
                                        {{ data.colKey }}
                                        <el-input v-model="data.alias" placeholder="Please input" />
                                        <!-- <el-checkbox v-model="data.visible" size="large" /> -->
                                        <span >
                                            <el-button v-if="data.visible" @click="changeVisible(data)" link >
                                                <el-icon>
                                                    <View />
                                                </el-icon>
                                            </el-button>
                                            <el-button v-if="!data.visible" @click="changeVisible(data)" link :class="{'fv-hide-col-active': !data.visible}">
                                                <el-icon>
                                                    <Hide />
                                                </el-icon>
                                            </el-button>
                                        </span>
                                    </div>
                                </template>
                            </el-tree>
                    </el-tab-pane>
                    <el-tab-pane label="Exported Files" v-if="selectedExportProfile != 'google-sheet'" class="fv-export-panel">
                        Export Files here
                        <el-table :data="exportProfileData.export_files" style="width: 100%">
                            <el-table-column prop="timestamp" label="Date" width="180" />
                            <el-table-column prop="exported_by" label="Exported By" width="180"/>
                            <el-table-column prop="file_name" label="File Name" />
                            <el-table-column width="120">
                                <template #default="scope">
                                    <el-button type="danger" :icon="Delete" circle  @click="onDeleteIcon(scope.row)" class="fv-ef-action-delete"/>
                                    <el-link :href="scope.row.filepath" :download="scope.row.file_name+'.csv'" :icon = "Download" class="fv-ef-action-download"></el-link>
                                </template>  
                            </el-table-column>
                        </el-table>
                        <div class="fv-table-pagination" v-if="exportProfileData.export_files.length > 10" >
                            <el-pagination
                                class="fv-pagination"
                                layout="total, sizes, prev, pager, next" 
                                :total="filesCount"
                                :current-page="currentPage"
                                :page-sizes="[10, 20, 30, 40,50]" 
                                :page-size="perPage"
                                @size-change="handleSizeChange"
                                @current-change="handleCurrentChange"
                            />
                        </div>
                    </el-tab-pane>
                    <el-tab-pane label="Columns Mapping" v-if="selectedExportProfile === 'google-sheet'" :disabled="askAddColumns">
                        <ColumnsMapping />
                    </el-tab-pane>
                </el-tabs>
            </div>
        </div>
    </el-config-provider>
</template>